import React, { useState } from 'react';
import Weather from './Weather';
import Forecast from './Forecast';
import { Circles } from 'react-loader-spinner';
import './index.css';

function App() {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);
  const [forecastData, setForecastData] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchWeather = async () => {
    const API_KEY = 'fe419969cef44122fe91d74e51878412'; // Replace this with your API key
    if (!city) return;

    try {
      setLoading(true);
      const currentRes = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${API_KEY}&units=metric`
      );
      const forecastRes = await fetch(
        `https://api.openweathermap.org/data/2.5/forecast?q=${city}&appid=${API_KEY}&units=metric`
      );

      if (!currentRes.ok || !forecastRes.ok) {
        throw new Error('City not found');
      }

      const currentData = await currentRes.json();
      const forecastData = await forecastRes.json();

      setWeatherData(currentData);
      setForecastData(forecastData);
      setError('');
    } catch (err) {
      setWeatherData(null);
      setForecastData(null);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app">
      <h1>Weather App</h1>
      <input
        type="text"
        placeholder="Enter city"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button onClick={fetchWeather}>Search</button>

      {error && <p className="error">{error}</p>}

      {loading && (
        <div style={{ marginTop: '20px' }}>
          <Circles height={80} width={80} color="blue" />
        </div>
      )}

      {!loading && weatherData && <Weather data={weatherData} />}
      {!loading && forecastData && <Forecast data={forecastData} />}
    </div>
  );
}

export default App;
